LEGACY_ANSWER_MAPPING;

    public function getDescription(): string
    {
        return 'Restore the audited legacy answer-to-question relations in the already-migrated Chamilo 2 database.';
    }

    public function isTransactional(): bool
    {
        return true;
    }

    public function up(Schema $schema): void
    {
        $this->requireTargetSchema($schema);

        $answerRows = (int) $this->connection->fetchOne(
            'SELECT COUNT(*) FROM c_quiz_answer'
        );
        $quiz305Questions = (int) $this->connection->fetchOne(
            'SELECT COUNT(*)
             FROM c_quiz_rel_question
             WHERE quiz_id = 305'
        );

        $this->abortIf(
            $answerRows < self::MINIMUM_TARGET_ANSWER_ROWS,
            \sprintf(
                'Legacy quiz answer relation repair refused because c_quiz_answer contains only %d rows.',
                $answerRows
            )
        );
        $this->abortIf(
            self::EXPECTED_QUIZ_305_QUESTIONS !== $quiz305Questions,
            \sprintf(
                'Legacy quiz answer relation repair requires the quiz-question repair first: quiz 305 has %d relations.',
                $quiz305Questions
            )
        );

        $mappingRows = $this->decodeMappingRows();

        $this->addSql(
            'DROP TEMPORARY TABLE IF EXISTS tmp_legacy_quiz_answer_guard'
        );
        $this->addSql(
            'DROP TEMPORARY TABLE IF EXISTS tmp_legacy_quiz_answer_map'
        );

        $this->addSql(<<<'SQL'
CREATE TEMPORARY TABLE tmp_legacy_quiz_answer_map (
    answer_iid INT UNSIGNED NOT NULL,
    question_iid INT NOT NULL,
    PRIMARY KEY (answer_iid),
    INDEX idx_tmp_legacy_answer_question (question_iid)
) ENGINE=InnoDB
SQL);

        $this->queueMappingRows($mappingRows);

        $this->addSql(
            'CREATE TEMPORARY TABLE tmp_legacy_quiz_answer_guard (
                id TINYINT NOT NULL PRIMARY KEY
             ) ENGINE=InnoDB'
        );
        $this->addSql(
            'INSERT INTO tmp_legacy_quiz_answer_guard (id) VALUES (1)'
        );

        $this->queueDuplicateKeyGuard(
            'SELECT 1
             WHERE (
                 SELECT COUNT(*)
                 FROM tmp_legacy_quiz_answer_map
             ) <> '.self::EXPECTED_MAPPING_ROWS
        );
        $this->queueDuplicateKeyGuard(
            'SELECT 1
             WHERE (
                 SELECT COUNT(DISTINCT question_iid)
                 FROM tmp_legacy_quiz_answer_map
             ) <> '.self::EXPECTED_MAPPING_QUESTIONS
        );
        $this->queueDuplicateKeyGuard(<<<'SQL'
SELECT 1
WHERE EXISTS (
    SELECT 1
    FROM tmp_legacy_quiz_answer_map mapping
    LEFT JOIN c_quiz_answer answer
        ON answer.iid = mapping.answer_iid
    WHERE answer.iid IS NULL
)
SQL);
        $this->queueDuplicateKeyGuard(<<<'SQL'
SELECT 1
WHERE EXISTS (
    SELECT 1
    FROM tmp_legacy_quiz_answer_map mapping
    LEFT JOIN c_quiz_question question
        ON question.iid = mapping.question_iid
    WHERE question.iid IS NULL
)
SQL);

        $this->addSql(<<<'SQL'
UPDATE c_quiz_answer answer
INNER JOIN tmp_legacy_quiz_answer_map mapping
    ON mapping.answer_iid = answer.iid
SET answer.question_id = mapping.question_iid
WHERE answer.question_id IS NULL
   OR answer.question_id <> mapping.question_iid
SQL);

        $this->queueDuplicateKeyGuard(<<<'SQL'
SELECT 1
WHERE EXISTS (
    SELECT 1
    FROM tmp_legacy_quiz_answer_map mapping
    INNER JOIN c_quiz_answer answer
        ON answer.iid = mapping.answer_iid
    WHERE answer.question_id IS NULL
       OR answer.question_id <> mapping.question_iid
)
SQL);
        $this->queueDuplicateKeyGuard(<<<'SQL'
SELECT 1
WHERE EXISTS (
    SELECT 1
    FROM c_quiz_answer answer
    INNER JOIN tmp_legacy_quiz_answer_map mapping
        ON mapping.answer_iid = answer.iid
    LEFT JOIN c_quiz_question question
        ON question.iid = answer.question_id
    WHERE question.iid IS NULL
)
SQL);

        $this->queueDuplicateKeyGuard(
            'SELECT 1
             WHERE (
                 SELECT COUNT(answer.iid)
                 FROM c_quiz_rel_question relation
                 INNER JOIN c_quiz_answer answer
                     ON answer.question_id = relation.question_id
                 WHERE relation.quiz_id = 305
             ) <> '.self::EXPECTED_QUIZ_305_ANSWER_ROWS
        );
        $this->queueDuplicateKeyGuard(
            'SELECT 1
             WHERE (
                 SELECT COUNT(DISTINCT relation.question_id)
                 FROM c_quiz_rel_question relation
                 INNER JOIN c_quiz_answer answer
                     ON answer.question_id = relation.question_id
                 WHERE relation.quiz_id = 305
             ) <> '.self::EXPECTED_QUIZ_305_QUESTIONS
        );
        $this->queueDuplicateKeyGuard(
            'SELECT 1
             WHERE (
                 SELECT COUNT(answer.iid)
                 FROM c_quiz_rel_question relation
                 INNER JOIN c_quiz_answer answer
                     ON answer.question_id = relation.question_id
                    AND answer.correct = 1
                 WHERE relation.quiz_id = 305
             ) <> '.self::EXPECTED_QUIZ_305_CORRECT_ANSWERS
        );

        $this->addSql(
            'DROP TEMPORARY TABLE tmp_legacy_quiz_answer_guard'
        );
        $this->addSql(
            'DROP TEMPORARY TABLE tmp_legacy_quiz_answer_map'
        );

        $this->write(\sprintf(
            'Legacy quiz answer relation repair queued: %d answers mapped to %d questions; quiz 305 must expose %d answers across %d questions.',
            self::EXPECTED_MAPPING_ROWS,
            self::EXPECTED_MAPPING_QUESTIONS,
            self::EXPECTED_QUIZ_305_ANSWER_ROWS,
            self::EXPECTED_QUIZ_305_QUESTIONS
        ));
    }

    public function down(Schema $schema): void
    {
        $this->abortIf(
            true,
            'This migration restores audited legacy answer relations and is intentionally irreversible.'
        );
    }

    /**
     * @return list<array{0: int, 1: int}>
     */
    private function decodeMappingRows(): array
    {
        $encoded = str_replace(
            ["\r", "\n"],
            '',
            self::MAPPING_GZIP_BASE64
        );
        $compressed = base64_decode($encoded, true);

        if (false === $compressed) {
            throw new RuntimeException('Unable to decode the embedded legacy quiz answer mapping.');
        }

        $raw = gzdecode($compressed);
        if (false === $raw) {
            throw new RuntimeException('Unable to decompress the embedded legacy quiz answer mapping.');
        }

        if (!hash_equals(self::MAPPING_SHA256, hash('sha256', $raw))) {
            throw new RuntimeException('The embedded legacy quiz answer mapping checksum is invalid.');
        }

        $rows = [];
        $answerIds = [];
        $questionIds = [];

        foreach (explode("\n", trim($raw)) as $lineNumber => $line) {
            if (
                1 !== preg_match(
                    '/^(\d+)\t(\d+)$/D',
                    $line,
                    $matches
                )
            ) {
                throw new RuntimeException(\sprintf('Invalid legacy quiz answer mapping row at line %d.', $lineNumber + 1));
            }

            $answerId = (int) $matches[1];
            $questionId = (int) $matches[2];

            if ($answerId <= 0 || $questionId <= 0) {
                throw new RuntimeException(\sprintf('Invalid legacy quiz answer mapping values at line %d.', $lineNumber + 1));
            }

            if (isset($answerIds[$answerId])) {
                throw new RuntimeException(\sprintf('Duplicate legacy answer iid at line %d.', $lineNumber + 1));
            }

            $answerIds[$answerId] = true;
            $questionIds[$questionId] = true;
            $rows[] = [$answerId, $questionId];
        }

        if (
            self::EXPECTED_MAPPING_ROWS !== \count($rows)
            || self::EXPECTED_MAPPING_QUESTIONS !== \count($questionIds)
        ) {
            throw new RuntimeException(\sprintf('Unexpected legacy quiz answer mapping size: answers=%d, questions=%d.', \count($rows), \count($questionIds)));
        }

        return $rows;
    }

    /**
     * @param list<array{0: int, 1: int}> $rows
     */
    private function queueMappingRows(array $rows): void
    {
        foreach (array_chunk($rows, self::INSERT_BATCH_SIZE) as $batch) {
            $values = [];

            foreach ($batch as [$answerId, $questionId]) {
                $values[] = \sprintf(
                    '(%d, %d)',
                    $answerId,
                    $questionId
                );
            }

            $this->addSql(
                'INSERT INTO tmp_legacy_quiz_answer_map (
                    answer_iid,
                    question_iid
                 ) VALUES '.implode(', ', $values)
            );
        }
    }

    private function queueDuplicateKeyGuard(string $invalidConditionSql): void
    {
        $this->addSql(
            'INSERT INTO tmp_legacy_quiz_answer_guard (id) '
            .$invalidConditionSql
        );
    }

    private function requireTargetSchema(Schema $schema): void
    {
        $requiredColumns = [
            'c_quiz_question' => ['iid'],
            'c_quiz_answer' => ['iid', 'question_id', 'correct'],
            'c_quiz_rel_question' => [
                'question_id',
                'quiz_id',
            ],
        ];

        foreach ($requiredColumns as $tableName => $columns) {
            $this->abortIf(
                !$schema->hasTable($tableName),
                \sprintf(
                    'Legacy quiz answer relation repair requires table %s.',
                    $tableName
                )
            );

            $table = $schema->getTable($tableName);
            foreach ($columns as $columnName) {
                $this->abortIf(
                    !$table->hasColumn($columnName),
                    \sprintf(
                        'Legacy quiz answer relation repair requires column %s.%s.',
                        $tableName,
                        $columnName
                    )
                );
            }
        }
    }
}
